#include <stdio.h>

int tongChuSo(int x) {
    int s = 0;
    while (x > 0) {
        s += x % 10;
        x /= 10;
    }
    return s;
}

int main() {
    int q;
    int a[25];
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        int v;
        scanf("%d", &v);
        a[i] = v;
    }
    int best = a[0];
    for (int i = 1; i < q; i++) {
        if (tongChuSo(a[i]) > tongChuSo(best)) best = a[i];
    }
    printf("%d %d\n", best, tongChuSo(best));
    return 0;
}

