void hoanDoi(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int main() {
    int n;
    int a[105];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int v;
        scanf("%d", &v);
        a[i] = v;
    }
    for (int i = 0; i < n / 2; i++) {
        hoanDoi(&a[i], &a[n - 1 - i]);
    }
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

