#include <stdio.h>

double trungBinh(int x, int y, int z) {
    return (x + y + z) / 3.0;
}

int main() {
    int n;
    int ma[55], a[55], b[55], c[55];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int m, x, y, z;
        scanf("%d %d %d %d", &m, &x, &y, &z);
        ma[i] = m; a[i] = x; b[i] = y; c[i] = z;
    }
    int best = 0, gioi = 0, truot = 0;
    for (int i = 0; i < n; i++) {
        double tb = trungBinh(a[i], b[i], c[i]);
        if (tb > trungBinh(a[best], b[best], c[best])) best = i;
        if (tb >= 8.0) gioi++;
        if (tb < 5.0) truot++;
    }
    printf("%d %.2f\n", ma[best], trungBinh(a[best], b[best], c[best]));
    printf("Gioi: %d\n", gioi);
    printf("Truot: %d\n", truot);
    return 0;
}

