#include <iostream>
using namespace std;

char g[15][15];
bool tham[15][15];
int n, m, dienTich;

void dfs(int r, int c) {
    if (r < 0 || c < 0 || r >= n || c >= m) return;
    if (g[r][c] != '#' || tham[r][c]) return;
    tham[r][c] = true;
    dienTich++;
    dfs(r + 1, c);
    dfs(r - 1, c);
    dfs(r, c + 1);
    dfs(r, c - 1);
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) cin >> g[i];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) tham[i][j] = false;
    int soDao = 0, lon = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (g[i][j] == '#' && !tham[i][j]) {
                soDao++;
                dienTich = 0;
                dfs(i, j);
                if (dienTich > lon) lon = dienTich;
            }
        }
    }
    cout << soDao << endl;
    cout << lon << endl;
    return 0;
}

