    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) cin >> g[i][j];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            f[i][j] = -1;
            if (g[i][j] < 0) continue;
            if (i == 0 && j == 0) {
                f[i][j] = g[i][j];
                continue;
            }
            long long best = -1;
            if (i > 0 && f[i - 1][j] > best) best = f[i - 1][j];
            if (j > 0 && f[i][j - 1] > best) best = f[i][j - 1];
            if (best >= 0) f[i][j] = best + g[i][j];
        }
    }
    cout << f[n - 1][m - 1] << endl;
    return 0;
}
